import { APP_INITIALIZER, makeEnvironmentProviders, inject } from '@angular/core'
import { ClerkService } from './clerk.service'
import type { BrowserClerk, ClerkServiceOptions } from './types'
import { ClerkClientFactory, CLERK_FACTORY_TOKEN } from './clerk-client-factory.service';

export function provideClerk(options: ClerkServiceOptions) {
  return makeEnvironmentProviders([
    ClerkService,
    {
      provide: CLERK_FACTORY_TOKEN,
      useFactory: () => ClerkClientFactory.createClient(options)
    },
    {
      provide: APP_INITIALIZER,
      useFactory: (factory: Promise<BrowserClerk | null>) => () => factory,
      deps: [CLERK_FACTORY_TOKEN],
      multi: true
    }
  ]);
}
