import { inject, InjectionToken } from '@angular/core'
import type { ClerkServiceOptions } from './types'
import { loadClerkJsScript } from '@clerk/shared/loadClerkJsScript';
import { Router } from '@angular/router';

export class ClerkClientFactory {
  static async createClient(options: ClerkServiceOptions) {
    const router = inject(Router);
    
    return loadClerkJsScript(options).then(async () => {
      if (!window.Clerk) {
        throw new Error('Failed to download latest ClerkJS. Contact support@clerk.com.');
      }

      await window.Clerk.load({
        ...options,
        routerPush: (to) => router.navigate([to]),
        routerReplace: (to) => router.navigate([to], { replaceUrl: true }),
      });
      return window.Clerk;
    })
  }
}

export const CLERK_FACTORY_TOKEN = new InjectionToken<ClerkClientFactory>('CLERK_FACTORY_TOKEN');
