import { Directive, ElementRef, inject, input, effect } from '@angular/core';
import { ClerkService } from './clerk.service';

interface ClerkRendererInputs {
  mount?: (node: HTMLDivElement, props: any) => void;
  unmount?: (node: HTMLDivElement) => void;
  props?: Record<string, any>;
}

@Directive({
  selector: '[clerkHostRenderer]',
  standalone: true,
})
export class ClerkDirective {
  #elementRef = inject(ElementRef)
  #clerkService = inject(ClerkService)
  #initialized = false;

  props = input<ClerkRendererInputs | undefined>(undefined, { alias: 'clerkHostRenderer' });

  constructor() {
    effect(() => {
      const element = this.#elementRef.nativeElement;
      const loaded = this.#clerkService.loaded();

      if (!element || !loaded) {
        return;
      }

      const mount = this.props()?.mount;
      const unmount = this.props()?.unmount;
      const props = this.props()?.props || {};

      if (this.#initialized) {
        // @ts-expect-error: Not exposed API
        this.#clerkService.clerk()?.__unstable__updateProps({ node: element, props });
        return;
      }

      mount?.(element, props);

      this.#initialized = true;

      return () => {
        unmount?.(element);
      };
    });
  }
}
