import { computed, inject, Injectable, signal } from '@angular/core';
import { deriveState } from '@clerk/shared/deriveState';
import type { Clerk, ClientResource, Resources } from '@clerk/types';
import { BrowserClerk } from './types';
import { CLERK_FACTORY_TOKEN } from './clerk-client-factory.service';

@Injectable({ providedIn: 'root' })
export class ClerkService {
  #clerkClient = inject<Promise<BrowserClerk>>(CLERK_FACTORY_TOKEN)
  #initialized = false;

  clerk = signal<Clerk | null>(null)
  loaded = signal(false)
  #resources = signal<Resources>({
    client: undefined as unknown as ClientResource,
    session: undefined,
    user: undefined,
    organization: undefined,
  })
  #derivedState = computed(() => deriveState(this.loaded(), this.#resources(), undefined));
  auth = computed(() => {
    const {
      sessionId,
      userId,
      orgId,
      actor,
      orgRole,
      orgSlug,
      orgPermissions,
      sessionStatus,
      sessionClaims,
      factorVerificationAge,
    } = this.#derivedState();
    return {
      sessionId,
      userId,
      actor,
      orgId,
      orgRole,
      orgSlug,
      orgPermissions,
      sessionStatus,
      sessionClaims,
      factorVerificationAge,
    };
  });
  client = computed(() => this.#resources().client);
  user = computed(() => this.#resources().user);
  session = computed(() => this.#resources().session);
  organization = computed(() => this.#resources().organization);

  constructor() {
    if (!this.#initialized) {
      this.#clerkClient.then(async (clerk) => {
        this.#initialized = true;

        this.clerk.set(window.Clerk);
        this.loaded.set(true);

        clerk.addListener(payload => {
          this.#resources.set(payload);
        });
      })
    }
  }
}
