import { Component, inject, input } from '@angular/core';
import type { SignInProps } from '@clerk/types';

import { ClerkDirective } from '../clerk.directive';
import { ClerkService } from '../clerk.service';

@Component({
  selector: 'clerk-sign-in',
  standalone: true,
  template: `
    <div
      [clerkHostRenderer]="{
        mount: clerkService.clerk()?.mountSignIn,
        unmount: clerkService.clerk()?.unmountSignIn,
        props: props()
      }"
    ></div>
  `,
  imports: [ClerkDirective],
})
export class ClerkSignInComponent {
  props = input<SignInProps>();
  clerkService = inject(ClerkService);

  constructor() {}
}
