import { Component, inject, input } from '@angular/core';
import type { SignUpProps } from '@clerk/types';

import { ClerkDirective } from '../clerk.directive';
import { ClerkService } from '../clerk.service';

@Component({
  selector: 'clerk-sign-up',
  standalone: true,
  template: `
    <div
      [clerkHostRenderer]="{
        mount: clerkService.clerk()?.mountSignUp,
        unmount: clerkService.clerk()?.unmountSignUp,
        props: props()
      }"
    ></div>
  `,
  imports: [ClerkDirective],
})
export class ClerkSignUpComponent {
  props = input<SignUpProps>();
  clerkService = inject(ClerkService);

  constructor() {}
}
