import { Component, inject, input } from '@angular/core';
import type { WaitlistProps } from '@clerk/types';

import { ClerkDirective } from '../clerk.directive';
import { ClerkService } from '../clerk.service';

@Component({
  selector: 'clerk-waitlist',
  standalone: true,
  template: `
    <div
      [clerkHostRenderer]="{
        mount: clerkService.clerk()?.mountWaitlist,
        unmount: clerkService.clerk()?.unmountWaitlist,
        props: props()
      }"
    ></div>
  `,
  imports: [ClerkDirective],
})
export class ClerkWaitlistComponent {
  props = input<WaitlistProps>();
  clerkService = inject(ClerkService);

  constructor() {}
}
